INSERT INTO "Announcement" ("id", "orgId", "authorMembershipId", "title", "body", "pinned", "createdAt") VALUES
('cmtwwu7ev00kerq79qxj25cxx', 'cmtwwu73x000drq791s0248sv', 'cmtwwu7450013rq79pk8312z0', 'Welcome to OrgOS 🎉', 'We have moved all operations into OrgOS — projects, CRM, HR and finance now live in one connected workspace. Explore the dashboard and let HR know if anything looks off.', 1, 1788350772487),
('cmtwwu7ew00kgrq79wqf7z17v', 'cmtwwu73x000drq791s0248sv', 'cmtwwu7460015rq79fvovbl0c', 'Q3 All-hands — Friday 4:00 PM', 'Agenda: Q3 results, GreenGrocer go-live plan, hiring pipeline and the new remote policy. Please add questions to the doc before Thursday.', 0, 1788782772487),
('cmtwwu7ew00kirq79j9nnos0z', 'cmtwwu73x000drq791s0248sv', 'cmtwwu7490019rq79u6qjbab1', 'New leave policy effective this month', 'Annual leave balance now accrues monthly. Casual leave requests need 48h notice except emergencies. Full policy in Documents → Policies.', 0, 1788523572488),
('cmtwwu7ex00kkrq79bqcbwn1i', 'cmtwwu73x000drq791s0248sv', 'cmtwwu7470017rq794ct6y1a5', 'GreenGrocer milestone 2 signed off ✅', 'Great work team — Core Commerce milestone accepted by client ahead of schedule. Next stop: integrations and migration.', 0, 1788955572489),
('cmtwwu7ex00kmrq79b6lqxvuu', 'cmtwwu73x000drq791s0248sv', 'cmtwwu7490019rq79u6qjbab1', 'Office closed — Victory Day (16 Dec)', 'The office will remain closed on 16 December. Client communications will resume the next working day.', 0, 1789041972489);
INSERT INTO "Job" ("id", "orgId", "title", "departmentId", "description", "responsibilities", "requirements", "skills", "experienceLevel", "employmentType", "location", "workMode", "salaryMin", "salaryMax", "currency", "deadline", "openings", "visibility", "status", "hiringManagerMembershipId", "createdAt") VALUES
('cmtwwu79600aqrq79tdw7489w', 'cmtwwu73x000drq791s0248sv', 'Senior Backend Engineer', 'cmtwwu740000hrq7986phx8cp', 'Own critical backend services for client platforms — payments, integrations and data pipelines.', 'Design and evolve service architecture. Mentor mid-level engineers. Own uptime of delivered systems.', 'Node.js/TypeScript, PostgreSQL, Redis, message queues, CI/CD, 5+ years.', 'Communication, Ownership, Craft', 'SENIOR', 'FULL_TIME', 'Dhaka, Bangladesh', 'REMOTE', 120000, 180000, 'BDT', 1791720372282, 2, 'PUBLIC', 'OPEN', 'cmtwwu7470017rq794ct6y1a5', 1789128372283),
('cmtwwu79700asrq7929vwjpvz', 'cmtwwu73x000drq791s0248sv', 'Product Designer', 'cmtwwu740000jrq79i8nl08st', 'Craft end-to-end product experiences across web and mobile for client projects.', 'Run discovery, wireframe, prototype, hand-off. Contribute to the shared design system.', 'Figma, design systems, portfolio of shipped web products, 3+ years.', 'Communication, Ownership, Craft', 'MID', 'FULL_TIME', 'Dhaka, Bangladesh', 'HYBRID', 80000, 120000, 'BDT', 1790856372283, 1, 'PLATFORM', 'OPEN', 'cmtwwu74g001lrq79edl87tgz', 1789128372284),
('cmtwwu79900aurq79qiug3vuq', 'cmtwwu73x000drq791s0248sv', 'Marketing Intern', 'cmtwwu741000lrq79am9vy0bk', 'Support campaign execution, content calendars and analytics reporting.', 'Draft social copy, assemble reports, coordinate with designers.', 'Final-year student or fresh graduate, strong writing, curiosity for analytics.', 'Communication, Ownership, Craft', 'ENTRY', 'INTERN', 'Dhaka, Bangladesh', 'ONSITE', 15000, 20000, 'BDT', 1790165172284, 2, 'PUBLIC', 'OPEN', 'cmtwwu74h001nrq791cz52fbs', 1789128372285),
('cmtwwu79a00awrq79bnsuczzt', 'cmtwwu73x000drq791s0248sv', 'QA Engineer (Contract)', 'cmtwwu740000hrq7986phx8cp', 'Manual + automated QA across active client projects.', 'Write and run test plans, automate regression, report defects.', 'Playwright, API testing, 3+ years agency experience.', 'Communication, Ownership, Craft', 'MID', 'FULL_TIME', 'Dhaka, Bangladesh', 'ONSITE', 60000, 80000, 'BDT', 1789128372285, 1, 'PRIVATE', 'PAUSED', 'cmtwwu7470017rq794ct6y1a5', 1789128372286);
